trace.raw_response:
```php
<?php
$N = (int)$argv[1];

$IM = 139968;
$IA = 3877;
$IC = 29573;
$SEED0 = 42;

// ALU sequence (287 chars) as given in the problem
$alu = "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" .
       "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" .
       "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" .
       "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" .
       "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

// IUB ambiguity codes table
$iubProbs = [0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02];
$iubChars = ['a','c','g','t','B','D','H','K','M','N','R','S','V','W','Y'];
$iubCum = [];
$cp = 0.0;
foreach ($iubProbs as $p) { $cp += $p; $iubCum[] = $cp; }

$iubLookup = str_repeat(' ', $IM);
for ($s = 0; $s < $IM; $s++) {
    $r = $s / $IM;
    for ($j = 0; $j < 15; $j++) {
        if ($r < $iubCum[$j]) {
            $iubLookup[$s] = $iubChars[$j];
            break;
        }
    }
}

// Homo sapiens frequency table
$homoProbs = [0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008];
$homoChars = ['a','c','g','t'];
$homoCum = [];
$cp = 0.0;
foreach ($homoProbs as $p) { $cp += $p; $homoCum[] = $cp; }

$homoLookup = str_repeat(' ', $IM);
for ($s = 0; $s < $IM; $s++) {
    $r = $s / $IM;
    for ($j = 0; $j < 4; $j++) {
        if ($r < $homoCum[$j]) {
            $homoLookup[$s] = $homoChars[$j];
            break;
        }
    }
}

// Generate one full period of the LCG output for each table
$seed = $SEED0;
$iubPeriod = '';
$homoPeriod = '';
for ($i = 0; $i < $IM; $i++) {
    $seed = ($seed * $IA + $IC) % $IM;
    $iubPeriod .= $iubLookup[$seed];
    $homoPeriod .= $homoLookup[$seed];
}

$stdout = fopen('php://stdout', 'wb');

// -------------------- Section ONE --------------------
$M = 2 * $N;
$aluSeqBlock  = str_repeat($alu, 60);           // 60 repeats = 17220 chars
$aluWrapBlock = chunk_split($aluSeqBlock, 60, "\n");
$blockLen = 17220;

fwrite($stdout, ">ONE Homo sapiens alu\n");
$full = (int)($M / $blockLen);
for ($i = 0; $i < $full; $i++) {
    fwrite($stdout, $aluWrapBlock);
}
$rem = $M % $blockLen;
if ($rem > 0) {
    fwrite($stdout, chunk_split(substr($aluSeqBlock, 0, $rem), 60, "\n"));
}

// -------------------- Section TWO --------------------
$M = 3 * $N;
$iubSeqBlock  = str_repeat($iubPeriod, 5);      // 5 periods = 699840 chars
$iubWrapBlock = chunk_split($iubSeqBlock, 60, "\n");
$blockLen = 699840;

fwrite($stdout, ">TWO IUB ambiguity codes\n");
$full = (int)($M / $blockLen);
for ($i = 0; $i < $full; $i++) {
    fwrite($stdout, $iubWrapBlock);
}
$rem = $M % $blockLen;
if ($rem > 0) {
    fwrite($stdout, chunk_split(substr($iubSeqBlock, 0, $rem), 60, "\n"));
}

// -------------------- Section THREE --------------------
$M = 5 * $N;
$start = (3 * $N) % $IM;
$pre  = substr($homoPeriod, $start);
$post = substr($homoPeriod, 0, $start);
$homoSeqBlock  = $pre . str_repeat($homoPeriod, 4) . $post; // 5 periods = 699840 chars
$homoWrapBlock = chunk_split($homoSeqBlock, 60, "\n");
$blockLen = 699840;

fwrite($stdout, ">THREE Homo sapiens frequency\n");
$full = (int)($M / $blockLen);
for ($i = 0; $i < $full; $i++) {
    fwrite($stdout, $homoWrapBlock);
}
$rem = $M % $blockLen;
if ($rem > 0) {
    fwrite($stdout, chunk_split(substr($homoSeqBlock, 0, $rem), 60, "\n"));
}

fclose($stdout);
```

